INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('e1ba85a3-71f1-4b63-850c-453ae32e2bc6', '21feff02-016d-46e2-bb9d-c27495133b1b', '1. óra: Az év bevezetése, ismétlés, játékos bevezető', 'Éves munkarend, elvárások, játékos feladatok az éves munka elkezdéséhez.', 'Matematika', '6. osztály', 'Év eleji ismétlés, diagnosztika', '[{"id": "6a9ed427-782e-4221-8159-c41b8c896ef7", "text": "Mi az éves matematika munka legfőbb célja?", "type": "multiple-choice", "options": [{"id": "343fe920-011e-456e-aae5-20b04d695952", "text": "A gondolkodási képesség és matematikai tudás fejlesztése", "isCorrect": true}, {"id": "07abb632-2f37-4126-8222-09a0f1f1cf5e", "text": "A könyvek visszagyűjtése", "isCorrect": false}, {"id": "fc5f1233-52fb-4074-8270-3bc2b896a76c", "text": "Csak a házi feladat írása", "isCorrect": false}, {"id": "00a4595d-d19f-4df8-a598-a595969184de", "text": "A számonkérések elkerülése", "isCorrect": false}], "timeLimit": 15}, {"id": "5b7c8876-2c93-4cff-88fe-98521837762c", "text": "A játékos matematikai feladatok segítik a tanulásra való ráhangolódást.", "type": "true-false", "options": [{"id": "88f095b4-96a9-4c23-95bc-53a31bfdb335", "text": "Igaz", "isCorrect": true}, {"id": "8ad7e536-3e85-40d8-bb8f-5f7aac667648", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "320802fe-609d-47f7-8b8e-8832b05006b8", "text": "Hány hétből áll egy átlagos magyar tanév?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "7607a16d-af51-4ae6-a93c-db113ea0ddf5", "text": "Melyik állítás ír le helyes tanulási magatartást?", "type": "multiple-choice", "options": [{"id": "dfcc05c7-b523-44b5-9018-f253c79c16a9", "text": "Rendszeres felkészülés és a hibák megbeszélése", "isCorrect": true}, {"id": "d8493d77-ee52-44a1-9ed1-5b58aab15295", "text": "Minden feladat feladása az első hibánál", "isCorrect": false}, {"id": "0ae947f6-3bf4-4009-b8ca-44d158662b35", "text": "A füzet otthon hagyása", "isCorrect": false}, {"id": "784a383a-188b-4a03-b2d7-9485eb916f9b", "text": "Másolás a padtárstól", "isCorrect": false}], "timeLimit": 15}, {"id": "b266606e-e8b2-4351-b752-a466589fe899", "text": "Mennyi a 25 + 75 összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "8ff4f940-f7ed-41d7-a78f-052f744aa2e8", "text": "A matematikai órákon a csoportmunka során fontos a kooperáció és egymás segítése.", "type": "true-false", "options": [{"id": "724d50bc-9974-4c73-b08c-72200a16a40c", "text": "Igaz", "isCorrect": true}, {"id": "182c8e86-d5c2-4c26-ba99-4ebb9ac45ae4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e43b8763-57a9-4d81-a830-fb4db8cf682d", "text": "Mennyi 8 * 9?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "72"}]'::jsonb, true, NOW()),
('ffd682dd-ff29-4c25-815a-763b21d92fec', '21feff02-016d-46e2-bb9d-c27495133b1b', '2. óra: Játékok', 'Játékszabályok, stratégiák, logikai gondolkodás páros és csoportmunkában.', 'Matematika', '6. osztály', 'Év eleji ismétlés, diagnosztika', '[{"id": "fe552469-8550-4443-8077-308db4644e45", "text": "Mi a stratégiai játékok lényege?", "type": "multiple-choice", "options": [{"id": "88eab0b4-0acc-4dc1-92ea-1c18caabc71e", "text": "Előre megtervezett lépésekkel a cél elérése", "isCorrect": true}, {"id": "a5209ca2-26c5-495d-8308-91a1c90ded50", "text": "Kizárólag a szerencsére hagyatkozás", "isCorrect": false}, {"id": "448839e0-90c1-4d9f-bf2b-38ea5573393e", "text": "Kockadobás számolás nélkül", "isCorrect": false}, {"id": "b4bd831e-4f69-431d-8777-feab6597cc7b", "text": "A szabályok figyelmen kívül hagyása", "isCorrect": false}], "timeLimit": 15}, {"id": "53c5d90a-e629-421b-ad87-09ef53f16230", "text": "A páros és csoportmunka során fontos a csapattársak véleményének meghallgatása.", "type": "true-false", "options": [{"id": "9b002d19-1e16-4571-bbf2-003c59e6ccfe", "text": "Igaz", "isCorrect": true}, {"id": "5b6c114b-cc1d-40ee-a402-51bc8056d611", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c2398e03-d0d3-4c51-a476-d71011fd70d2", "text": "Hány mezőből áll egy klasszikus 8x8-as sakktábla?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "e581e490-22c2-4fdb-83f2-c5028301dccb", "text": "Melyik játék fejleszti kifejezetten a logikai gondolkodást és a számolást?", "type": "multiple-choice", "options": [{"id": "15ef300c-ad77-4443-bfd6-549c74fd1f55", "text": "Sudoku", "isCorrect": true}, {"id": "001d06d6-92cf-4083-ae9e-17f8e80da710", "text": "Fócsoport", "isCorrect": false}, {"id": "fe471124-4dd2-406e-836c-fea41d198122", "text": "Futóverseny", "isCorrect": false}, {"id": "3885532e-13b2-4696-8f0b-c4ec1f7d8d2f", "text": "Kő-papír-olló", "isCorrect": false}], "timeLimit": 15}, {"id": "d7046fbc-29f0-472e-8c29-396df14e1171", "text": "A bűvös négyzetben minden sor, oszlop és átló összege megegyezik.", "type": "true-false", "options": [{"id": "ed4db030-3de0-42fd-838e-1c1ed9ea3214", "text": "Igaz", "isCorrect": true}, {"id": "ecdfd514-3c46-4b71-9801-b43e5092a1f5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "00a21c7b-0bbd-4b49-a1ab-52890dd41fd6", "text": "Mennyi az 1, 2, 3, 4, 5 számok összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "f2ac6247-34f9-4ea7-a423-350b6e18fe24", "text": "A szabályok betartása elengedhetetlen a fair play játékban.", "type": "true-false", "options": [{"id": "77cc1da5-f36a-4483-beae-f03bcd8117f8", "text": "Igaz", "isCorrect": true}, {"id": "b06e5b83-93a6-420e-8c11-ad6fa5965984", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('370232b9-0c14-4e8b-8c71-ccabea251dfd', '21feff02-016d-46e2-bb9d-c27495133b1b', '3. óra: Év eleji diagnosztikus felmérés', 'Az 5. osztályban tanult ismeretek felmérése, tudásszint diagnosztizálása.', 'Matematika', '6. osztály', 'Év eleji ismétlés, diagnosztika', '[{"id": "2f77310f-59a8-439a-a23e-a7a715709982", "text": "1. Mennyi (-12) + 5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-7"}, {"id": "e4ff9458-3599-47cd-8de9-e7c7cc298171", "text": "2. Mennyi 3/4 + 1/4?", "type": "multiple-choice", "options": [{"id": "41df66ed-b856-40cb-834f-2f4397402f49", "text": "1 egész (4/4)", "isCorrect": true}, {"id": "2fd94a98-b1ed-424f-97e0-e0354a12da5f", "text": "2/4", "isCorrect": false}, {"id": "8e01edac-3f54-4e4f-94dc-c58d59f01da7", "text": "4/8", "isCorrect": false}, {"id": "96e53c91-eb77-4e9f-a067-c3f2e83a7dd4", "text": "3/8", "isCorrect": false}], "timeLimit": 15}, {"id": "43797084-4927-43d0-95b6-e59fe82f6954", "text": "3. Mennyi a 4 cm oldalú négyzet kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "d1fe40b5-6032-47a0-9fc5-f2f83b8078f1", "text": "4. Mennyi a 4 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "cc455181-4025-45d1-ba83-b68a16f1bba7", "text": "5. Hány gramm 2,5 kg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "459ff239-db7b-48b8-814c-72bd77d411ab", "text": "6. A negatív számok a nullától balra találhatók a számegyenesen.", "type": "true-false", "options": [{"id": "9f92cf1a-641b-403c-99c8-4bddee57ee1b", "text": "Igaz", "isCorrect": true}, {"id": "fa0ac2da-9565-48aa-83c1-520856362cd0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "81ae34c9-6a7e-446c-944b-f17e831473ec", "text": "7. Hány perc 1 és fél óra?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "e6664327-6f3a-412f-b663-2d6a51dadc0b", "text": "8. Mennyi 0,5 + 0,7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.2"}, {"id": "61489522-3e9a-4425-b976-ac87a790bea2", "text": "9. A derékszögű háromszögnek van egy 90°-os szöge.", "type": "true-false", "options": [{"id": "1b4efbed-a2e9-4a31-b0d7-59698c3d4ae2", "text": "Igaz", "isCorrect": true}, {"id": "61faa4a9-aa0c-4f5e-a8f7-2ed792947b51", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bf40dcc5-8641-410e-a644-cfa30d43e25f", "text": "10. Hány csúcsa van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]'::jsonb, true, NOW()),
('5a0d583e-5cfd-4e20-a0c4-a2d39bd64561', '21feff02-016d-46e2-bb9d-c27495133b1b', '4. óra: Műveletek az egész számok körében', 'Mit tanultunk ötödik osztályban? A felmérés tapasztalatainak feldolgozása, hibajavítás.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "9ac9f147-10b8-456e-9385-29200dc254df", "text": "Mennyi (-8) + (+15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "2b601ce6-b6e5-4aa5-814f-92d6f3c73a76", "text": "Mennyi (-6) - (+4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-10"}, {"id": "f93ae524-ff18-4d53-b42c-a827de5399dd", "text": "Az ellentett számok összege mindig 0.", "type": "true-false", "options": [{"id": "5c799206-fc9a-40c2-b075-8613d13c5a3a", "text": "Igaz", "isCorrect": true}, {"id": "ed308187-8c52-4d7d-a237-cf22f11cc0ec", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "10316876-29a6-4301-9490-56299a2e81a3", "text": "Mennyi |-25| (a -25 abszolút értéke)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "812acf1e-f3f2-4214-859a-9267eaf0ffd3", "text": "Melyik szám nagyobb: -15 vagy -8?", "type": "multiple-choice", "options": [{"id": "6ece2424-81d8-4b40-8c60-ad54e7352453", "text": "-8", "isCorrect": true}, {"id": "ebe6b172-8586-472c-8a93-4584851160e8", "text": "-15", "isCorrect": false}, {"id": "6fd64879-1e6a-4b1c-ad2c-50d9c0bdd1c7", "text": "Egyenlőek", "isCorrect": false}, {"id": "9e2a7d32-16c5-4275-bed3-522c69349db7", "text": "Nem összehasonlítható", "isCorrect": false}], "timeLimit": 15}, {"id": "e4edfd7e-0f7b-444c-b359-87b5403b52ee", "text": "A nullánál kisebb számokat negatív számoknak nevezzük.", "type": "true-false", "options": [{"id": "928f96a0-e7a5-466c-bf1a-91eb6927ab40", "text": "Igaz", "isCorrect": true}, {"id": "432c9005-55a9-4ab6-8972-9a724c73d5a1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "15c5cfff-e466-4b95-a02d-a97c837d588c", "text": "Mennyi (-10) + (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}]'::jsonb, true, NOW()),
('f871fb52-0bd9-4c47-aa3c-12448171a456', '21feff02-016d-46e2-bb9d-c27495133b1b', '5. óra: Az egész számok szorzása', 'Negatív számokkal való szorzás, az előjelszabály megértése és alkalmazása.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "bd9c67ad-4fa2-4504-b56b-970465816b37", "text": "Mi az előjelszabály két negatív szám szorzásakor? (- * -)", "type": "multiple-choice", "options": [{"id": "bcd25c65-5e18-4c6e-9c40-2b67abfce8b6", "text": "Pozitív (+)", "isCorrect": true}, {"id": "7eac2c82-1fb7-46b1-a13d-161b7c69f3b8", "text": "Negatív (-)", "isCorrect": false}, {"id": "619f7d89-9b5f-4b98-a96c-bbb1f6c0bea6", "text": "Mindig 0", "isCorrect": false}, {"id": "91c033d4-7717-43a5-affd-70876b72ed7f", "text": "Nem lehet megszorozni", "isCorrect": false}], "timeLimit": 15}, {"id": "33d20aae-6519-47e3-8a3b-a1f4ace1a024", "text": "Mennyi (-4) * (+5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-20"}, {"id": "71739728-03bb-4f16-89ca-e9e7d4399bc4", "text": "Mennyi (-6) * (-7)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "42"}, {"id": "f6d75b44-216d-41d0-85d5-0d7caf94adea", "text": "Egy pozitív és egy negatív szám szorzata mindig negatív.", "type": "true-false", "options": [{"id": "a454bd38-d2e6-4f2c-9a90-910dbb96b4ed", "text": "Igaz", "isCorrect": true}, {"id": "e3111bd7-e7cf-47f1-afcf-9b9543279391", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bbf86b99-7c9b-4fc9-9caf-6320314491d8", "text": "Mennyi (-3) * 0?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0"}, {"id": "3fe4b2cc-98dd-44c2-ad3e-4e1bdf40d6cc", "text": "Ha három negatív számot szorzunk össze, a szorzat előjele negatív lesz.", "type": "true-false", "options": [{"id": "c654453e-78f0-4982-94e0-fa869fc1a1cc", "text": "Igaz (- * - * - = -)", "isCorrect": true}, {"id": "ab46ac6b-89ac-48e9-8761-5fe22625e571", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cb1e817c-39c8-4bba-aa34-5abfd3fc1234", "text": "Mennyi (-2) * (-3) * (-4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-24"}]'::jsonb, true, NOW()),
('8551091d-d1ea-49f6-a599-451c4175c315', '21feff02-016d-46e2-bb9d-c27495133b1b', '6. óra: Gyakorlóóra: az egész számok szorzása', 'Több tényező előjelének meghatározása, szorzások gyakorlása.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "2cd55dfd-34bd-4054-bd3c-8dd8a589c7ac", "text": "Mennyi (-5) * (-2) * (+3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "d400e7b7-bfce-4501-9532-dd7659608c48", "text": "Ha egy szorzatban páros számú negatív tényező van, a szorzat előjele:", "type": "multiple-choice", "options": [{"id": "bd06ee95-03c1-44be-b786-fa2eb33d9d55", "text": "Pozitív", "isCorrect": true}, {"id": "78a9015f-a653-44c5-8ec7-86e8aef78e6c", "text": "Negatív", "isCorrect": false}, {"id": "a4ce6856-4d36-4456-a76b-46729de501a5", "text": "Nulla", "isCorrect": false}, {"id": "fe9fedd3-fb44-4d5f-befd-f4cd5463d865", "text": "Változó", "isCorrect": false}], "timeLimit": 15}, {"id": "9f51eadd-4a80-4f3a-9d8e-ca6f2319dd0b", "text": "Mennyi (-10) * (-10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "5396bc57-5264-40d3-bf01-fe3ccde5b283", "text": "A 0-val való szorzás eredménye mindig 0.", "type": "true-false", "options": [{"id": "62029d36-8b44-4f69-a106-3ebb40b7d752", "text": "Igaz", "isCorrect": true}, {"id": "23a0d377-87f6-4e27-9c16-ee079523a2e7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e2a63ae9-7e20-4985-b45c-ea77479c099a", "text": "Mennyi (-1) * (+15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}, {"id": "219ec3bb-a96c-4a02-a92a-056c7a5712f2", "text": "Mennyi a (-2) köbe ( (-2) * (-2) * (-2) )?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-8"}, {"id": "988bb032-1061-4929-a89b-fa88dc410232", "text": "Az írásbeli szorzáskor az előjelet a művelet végzésétől függetlenül, az előjelszabály szerint állapítjuk meg.", "type": "true-false", "options": [{"id": "2afd9d85-2fd9-4c12-b16d-2e8d524f2fbb", "text": "Igaz", "isCorrect": true}, {"id": "f8a2b115-5043-4694-ab7e-3a9c40d2e5e1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('a5df8f7c-9278-4bd0-92a1-40e58e1f2a46', '21feff02-016d-46e2-bb9d-c27495133b1b', '7. óra: Az egész számok osztása', 'Negatív osztandó, osztóval végzett műveletek algoritmusa, előjelszabály osztásnál.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "5d97bc07-440a-4971-9476-2dc697f2ec4e", "text": "Mi az előjelszabály egész számok osztásakor?", "type": "multiple-choice", "options": [{"id": "e574bbfc-21ba-4cad-bbc7-16e900adbb30", "text": "Ugyanaz, mint a szorzásnál (+:+=+, -:-=+, +:-=-, -:+=-)", "isCorrect": true}, {"id": "79307f15-6c2c-4cc0-9b3b-88bef9489712", "text": "Mindig negatív", "isCorrect": false}, {"id": "2f69d794-6249-40aa-bb99-cb8b51cd92fe", "text": "Mindig pozitív", "isCorrect": false}, {"id": "5cd1e7fe-3fc3-4f0f-b13f-0eef33da9a21", "text": "Kivonást kell végezni", "isCorrect": false}], "timeLimit": 15}, {"id": "82e5e720-aaa5-4597-a093-6ec64f651a36", "text": "Mennyi (-20) : (+4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-5"}, {"id": "2acece72-287f-4281-b91b-9d14dcac7200", "text": "Mennyi (-36) : (-6)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "6dfb72f3-a962-48e0-b5df-44552bd0d7d4", "text": "Nullával osztani nem lehet a matematikában.", "type": "true-false", "options": [{"id": "aedbcf60-f5e8-4d7b-897e-a2b96d88cc3b", "text": "Igaz", "isCorrect": true}, {"id": "ba791ff4-8fbd-48e5-8209-d7e82367b932", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "00e5ce7f-37d7-4e82-abb1-c95dbaba22ee", "text": "Mennyi (+50) : (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-10"}, {"id": "94dff8d4-d5eb-4396-a0ad-3a353e7710ce", "text": "Ha a (-15)-öt elosztjuk (-3)-mal, az eredmény pozitív szám.", "type": "true-false", "options": [{"id": "0df1e805-b062-4bff-b4a9-ab265bd90b55", "text": "Igaz", "isCorrect": true}, {"id": "0ac3c049-ea0f-4539-8242-f267b129f13e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8f41664c-02fa-4627-afd8-1399f7c50c96", "text": "Mennyi 0 : (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0"}]'::jsonb, true, NOW()),
('8c0c875c-7e0d-4fba-b394-436d142fb501', '21feff02-016d-46e2-bb9d-c27495133b1b', '8. óra: Az egész számok osztásának gyakorlása', 'Írásbeli és fejben osztás gyakorlása negatív és pozitív számokkal.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "db93a494-10bc-4323-917f-500e73c15af8", "text": "Mennyi (-100) : (-25)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "e64b09b9-05a7-4945-9d3e-feef3a268f07", "text": "Mennyi (-48) : (+8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-6"}, {"id": "fb962cca-5266-4982-b1a5-bdd4cde69010", "text": "Melyik egyenlet helyes?", "type": "multiple-choice", "options": [{"id": "5b691334-8f6d-4881-8c59-61852be9cdff", "text": "(-18) : (-3) = 6", "isCorrect": true}, {"id": "33aed822-15da-4c04-87ea-e0c0522354f2", "text": "(-18) : (-3) = -6", "isCorrect": false}, {"id": "af1bd954-e288-408e-992a-a05b5e3394e8", "text": "(-18) : (+3) = 6", "isCorrect": false}, {"id": "754e6bfa-25e7-4798-9149-fed7ed1d7234", "text": "(+18) : (-3) = 6", "isCorrect": false}], "timeLimit": 15}, {"id": "0c08c37c-3cc8-4be1-a008-ac30cb324e94", "text": "A hányados ellenőrzése szorzással történik.", "type": "true-false", "options": [{"id": "2dd4c0bd-e618-4d36-96a3-f839cedad19b", "text": "Igaz", "isCorrect": true}, {"id": "78fb4839-7be4-4a7a-8231-802d8b53e6e6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fff42b9d-74a8-431d-b287-904e439e592c", "text": "Mennyi (-81) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-9"}, {"id": "84d02faf-a9a5-4128-99c7-cdcf0853bfd4", "text": "Ha két szám hányadosa pozitív, a két szám előjele azonos.", "type": "true-false", "options": [{"id": "5e83791b-cc5e-48fb-88d2-13b95e5c1866", "text": "Igaz", "isCorrect": true}, {"id": "64a714bf-9f33-43e5-ba90-0e086456412f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "85b0549d-1d1c-4d46-a559-9a7a7bcc758e", "text": "Mennyi (-144) : (-12)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW()),
('6c130ed5-9813-42f5-8fe2-e6d8a20d2b97', '21feff02-016d-46e2-bb9d-c27495133b1b', '9. óra: Hány eset van? Számoljuk össze!', 'Összeszámlálás fagráffal (ágrajz), táblázattal, rendszerezett felsorolással.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "eae5977a-8b00-4432-b5ee-adec7c3cf8f0", "text": "Milyen eszközt használhatunk az összes lehetőség rendszerezett szemléltetésére?", "type": "multiple-choice", "options": [{"id": "a3d8b9be-c5d1-470d-a1c1-3f110a5ab219", "text": "Fagráfot (ágrajzot) és táblázatot", "isCorrect": true}, {"id": "648f1497-4fcd-4866-8bbe-7979e90a715c", "text": "Szögmérőt", "isCorrect": false}, {"id": "ca6b72bf-8850-4c79-8e84-1e8ec2c65a33", "text": "Körzőt", "isCorrect": false}, {"id": "da0c74b1-71b3-4cc1-b668-6f000ebbf219", "text": "Vonalzót", "isCorrect": false}], "timeLimit": 15}, {"id": "b3e736d9-01cf-49ce-a1df-a1e291959718", "text": "Hányféleképpen ülhet le 2 gyerek (Peti és Kati) két egymás melletti székre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "c9689ff1-d35c-4240-93dc-cd23eda6733a", "text": "Hány különböző 2 jegyű szám képezhető az 1 és 2 számjegyekből (számjegyismétléssel)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "492f7337-5a57-40ff-935f-7f663fd9e37e", "text": "A rendszerezett felsorolás segít abban, hogy egyetlen lehetőséget se hagyjunk ki.", "type": "true-false", "options": [{"id": "1d9edb1c-404d-4629-bf90-b8bd09167ced", "text": "Igaz", "isCorrect": true}, {"id": "e36421d9-4cf7-42cf-8cbe-a37f0cb0aee9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "32180b19-f9df-4758-93ae-9b793b8c48f5", "text": "Hányféleképpen választhatunk ki 3 póló és 2 nadrág közül egy ruhakészletet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "d754a623-951e-4e82-93c4-3e498c3d0417", "text": "A kombinatorikai feladatoknál a sorrend mindig számít.", "type": "true-false", "options": [{"id": "f936e9b8-bce2-476c-9cf1-8e324f5c27ae", "text": "Igaz", "isCorrect": false}, {"id": "44ab3138-a0e2-441f-ab33-b7fef9655e70", "text": "Hamis (van ahol számít, van ahol nem)", "isCorrect": true}], "timeLimit": 15}, {"id": "0c0007a4-80a6-4ff6-8b96-99808a0d9ec9", "text": "Hány lapja van egy érmének (kimenetelek száma)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW()),
('09b78524-d9e3-4565-9a61-6c07324e48da', '21feff02-016d-46e2-bb9d-c27495133b1b', '10. óra: Gyakorlóóra. Hány eset van? Számoljuk össze!', 'Összeszámlálási feladatok gyakorlása fagráffal és táblázattal.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "5996dcc7-4170-474b-94f3-d4e1bde770aa", "text": "Hány 2 jegyű páros szám képezhető az 1, 2, 3 számjegyekből (számjegyismétlés nélkül)?", "type": "multiple-choice", "options": [{"id": "951d3a1a-89f5-4911-8664-cf4f5af1186c", "text": "2 (12, 32)", "isCorrect": true}, {"id": "36afcf6d-db6d-45ec-94f5-8f777bb01059", "text": "3", "isCorrect": false}, {"id": "271d0eec-2928-4212-bcc9-9f9bf81d672a", "text": "4", "isCorrect": false}, {"id": "3d731eb8-ae35-4e25-8afb-279450a7f193", "text": "6", "isCorrect": false}], "timeLimit": 15}, {"id": "22cb472a-19b1-4598-83f6-6d6cd3769d07", "text": "Három barát köszöntésekor (mindenki mindenkivel kezet fog) hány kézfogás történik?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "58ca0865-8b18-430b-80dc-fc509f45e0b1", "text": "A fagráf ágai az egyes döntési lépéseket ábrázolják.", "type": "true-false", "options": [{"id": "8aeb3034-4834-4117-8726-8590fb7ca5c0", "text": "Igaz", "isCorrect": true}, {"id": "5d196ced-c2d7-4836-b69f-6e4a2181e3bc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3822d5ce-18b8-4077-83e3-ce8d953de091", "text": "Hány különböző sorrendben futhat be a célba 3 versenyző (A, B, C)? (3! = 3*2*1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "4475bbd1-4f3d-447f-bd97-444ed56f2742", "text": "Ha 4 csapat játszik körmérkőzést (mindenki mindenkivel egyszer), hány mérkőzést játszanak összesen?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "0335999a-ce1a-48d1-9086-7c6cf7e324ae", "text": "Egy szabályos dobókocka eldobásakor 6-féle kimenetel lehetséges.", "type": "true-false", "options": [{"id": "fafc3641-b448-4fc6-bdda-05ae9c1bfaa4", "text": "Igaz", "isCorrect": true}, {"id": "e48fc68f-53cf-4b93-b4c0-a4947e8273e9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7cbfdde3-ebe2-498e-8bd3-b110a0185ae8", "text": "Hány kétjegyű szám képezhető a 0 és 5 számjegyekből (0 nem lehet az első számjegy)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW()),
('c016fafb-1321-4967-9c69-7fad1fd38a01', '21feff02-016d-46e2-bb9d-c27495133b1b', '11. óra: Összeszámlálási feladatok megoldása', 'Önálló feladatmegoldás rendszerezett felsorolással és faábrával.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "4de8c240-8cdc-42e9-a5e7-de19ddd15135", "text": "Hányféleképpen rakhatunk sorba 4 különböző könyvet a polcon? (4*3*2*1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "692466b2-24bc-4546-a848-b40d9dfbd8f5", "text": "Hány 3 jegyű szám képezhető a 7, 8, 9 számjegyekből ha mindegyiket csak egyszer használhatjuk fel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "33228604-c596-4537-99b1-56bf7734b7f8", "text": "Az ágrajz utolsó szintjén lévő levelek száma megadja az összes lehetséges kimenetelt.", "type": "true-false", "options": [{"id": "01c55682-ac90-436b-a0fa-605206e01f17", "text": "Igaz", "isCorrect": true}, {"id": "8b3b19dd-8a86-4dfb-a038-f238d4441142", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4ff58c67-de6e-48e4-b88b-0666fa6040e5", "text": "Melyik állítás igaz a valószínűségi kísérletekre?", "type": "multiple-choice", "options": [{"id": "673f4685-6639-48af-a029-476344d66a4c", "text": "A lehetséges esetek száma a kedvező és kedvezőtlen esetek összege", "isCorrect": true}, {"id": "bfb82482-3ae9-4c82-af51-3e380a78631c", "text": "Mindig csak 1 eset lehetséges", "isCorrect": false}, {"id": "2c8ec762-4c10-471d-b90b-9602cd7efcd9", "text": "Sohasem lehet kiszámolni az esetek számát", "isCorrect": false}, {"id": "cc8095a0-4fb5-4060-8ced-60889ff7e055", "text": "Csak páros szám lehet az eredmény", "isCorrect": false}], "timeLimit": 15}, {"id": "2c1ec2ef-746c-4cf4-b6a9-70fc509b2a30", "text": "Hányféle kétgombócos fagyit választhatunk 3-féle ízből, ha két különböző ízt kérünk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "e2290e9b-bd2a-480b-aca4-05f075a30692", "text": "Ha egy feldobott pénzérmét kétszer dobunk fel egymás után, a lehetséges kimenetelek száma 4.", "type": "true-false", "options": [{"id": "07b9b89a-6886-4b25-bb29-eb29859f2394", "text": "Igaz (FF, FI, IF, II)", "isCorrect": true}, {"id": "3755e7ee-e34f-41b9-b6c9-534152c3fd3b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "46f4849b-b805-4220-9299-5973dd31dcf0", "text": "Hány válaszlehetőség van egy 4 opciós feleletválasztós kérdésnél?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW()),
('88e2c066-2dc2-42e2-adad-53aa3a546ab5', '21feff02-016d-46e2-bb9d-c27495133b1b', '12. óra: Számonkérés', 'Az egész számok műveleteiből és az összeszámlálásból tanultak számonkérése (10 kérdés).', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "0828c353-1e41-4d86-ae5a-59819d407491", "text": "1. Mennyi (-15) + (+20)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "7c48d1ed-590c-4bfa-b28a-10141ca9b6f4", "text": "2. Mennyi (-6) * (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "ac3008fc-6f55-4d2a-8d30-b9901397f51a", "text": "3. Mennyi (-54) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-6"}, {"id": "9a39e9ba-aac6-4ed1-b80e-34e0f757dbac", "text": "4. Melyik szám abszolút értéke nagyobb: |-30| vagy |+20|?", "type": "multiple-choice", "options": [{"id": "4afb93d8-530b-4784-bbb5-ec2dab2fb538", "text": "|-30|", "isCorrect": true}, {"id": "1f0ac9ed-6b93-43e6-b773-b305b8736b56", "text": "|+20|", "isCorrect": false}, {"id": "159e0131-8498-48fb-be2c-8eb10ef6bb44", "text": "Egyenlőek", "isCorrect": false}, {"id": "8c2ca24d-3df0-4986-a396-e384872c0b12", "text": "Egyik sem", "isCorrect": false}], "timeLimit": 15}, {"id": "6301bac2-ee3e-4b40-b947-4aee9a3a4c14", "text": "5. Mennyi (-3) * (-2) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-30"}, {"id": "fbbfc15f-43dc-4509-9307-67870721c7c4", "text": "6. A negatív szám szorzása negatív számmal pozitív eredményt ad.", "type": "true-false", "options": [{"id": "aa362df3-3be5-4efa-9348-56e5522a8dae", "text": "Igaz", "isCorrect": true}, {"id": "5b98adab-6f30-416a-8158-e7236b50fe55", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "406002bc-e4a4-4ae5-a538-80cc6cb38f51", "text": "7. Hány különböző sorrendben ülhet le 3 gyerek egy padra?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "4d65fa8b-6089-4d88-8dd3-f4ac05de2f4c", "text": "8. Mennyi (-40) : (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "f515f6d6-50ad-4cd1-9db8-a90c28723120", "text": "9. A nullának nincs ellentettje (vagy önmaga az ellentettje).", "type": "true-false", "options": [{"id": "666fe726-2ce6-4235-9fa8-403770031726", "text": "Igaz", "isCorrect": true}, {"id": "1294c834-b78b-405a-b868-5674c563e368", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6fccaf2d-7dde-4e43-9e35-2e34d5be8bfa", "text": "10. Mennyi (-10) + (-20) - (-15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}]'::jsonb, true, NOW()),
('4303d578-d5f9-4bbf-a837-2f1029c084fe', '21feff02-016d-46e2-bb9d-c27495133b1b', '13. óra: Osztó, többszörös', 'Osztó, többszörös fogalma, osztópárok meghatározása.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "82e1ddd9-fe3e-409d-a468-576f734a6a91", "text": "Mit nevezünk egy ''a'' természetes szám osztójának?", "type": "multiple-choice", "options": [{"id": "3741f0f5-49e4-4985-b810-501022de4a08", "text": "Azt a ''b'' számot, amellyel ''a''-t elosztva a maradék 0", "isCorrect": true}, {"id": "fd40ecf4-832f-46b5-a8d1-2e6ba5708db3", "text": "Azt a számot, amit ''a''-hoz hozzáadunk", "isCorrect": false}, {"id": "6e0a4425-88d2-49d3-8361-bc6fd01dfc1f", "text": "Azt a számot, ami nagyobb ''a''-nál", "isCorrect": false}, {"id": "fb9cfb00-c8df-40fd-9fe9-6f3db3ddf530", "text": "Minden páratlan számot", "isCorrect": false}], "timeLimit": 15}, {"id": "5b91203b-2ae4-46de-813a-0ab1d1da0887", "text": "Az 1 minden természetes számnak osztója.", "type": "true-false", "options": [{"id": "fb5db186-bab9-43de-ba5c-ebba141186a7", "text": "Igaz", "isCorrect": true}, {"id": "ffe6fc1b-a126-4359-a937-5e92547a058c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "662b1bce-8065-455f-aa9f-c62c103fcc28", "text": "Hány osztója van a 12-nek? (1, 2, 3, 4, 6, 12)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "76a99289-7c44-47d3-a256-d472b305e010", "text": "Melyik szám a 15 többszöröse az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "f8a53f40-5234-4088-a459-72688a196979", "text": "45", "isCorrect": true}, {"id": "9c3c154e-a9c4-4521-980c-6f0a2bf2312e", "text": "5", "isCorrect": false}, {"id": "83b32335-dcc4-4110-92f2-f8a58655b043", "text": "3", "isCorrect": false}, {"id": "1028fd3f-fae0-4d3a-843d-67cdf358b6b7", "text": "10", "isCorrect": false}], "timeLimit": 15}, {"id": "7fd24697-a5d5-4c82-bd4d-d2dd298ece1e", "text": "Minden számnak végtelen sok többszöröse van.", "type": "true-false", "options": [{"id":